import assert from "node:assert/strict";
import { test } from "node:test";
import { branchOf, byBranch, isUntagged, matches, toEnvctlResource } from "../src/filter.ts";
import { buildPlan } from "../src/plan.ts";

function raw(id: string, fields: Record<string, unknown> = {}): Record<string, unknown> {
  return { id, type: "instance", name: id, ...fields };
}

test("CDK label keys are case-insensitive, while branch values stay exact", () => {
  for (const key of ["branch", "Branch", "BRANCH", "bRaNcH"]) {
    const resource = toEnvctlResource(raw("worker", { labels: { [key]: "Feat-Ledger", Team: "payments" } }));
    assert.equal(branchOf(resource), "Feat-Ledger");
    assert.equal(isUntagged(resource), false);
    assert.ok(matches(resource, [["team", "payments"]]));
    assert.equal(byBranch([resource]).get("Feat-Ledger")?.length, 1);
    assert.equal(buildPlan([resource], "feat-ledger").steps.length, 0);
    assert.equal(buildPlan([resource], "Feat-Ledger").steps.length, 1);
  }
});

test("normalization preserves legacy tags and defaults without mutating payloads", () => {
  const source = raw("legacy", {
    tags: { branch: "feat-other", owner: "legacy" },
    labels: { Branch: "feat-ledger", Team: "payments" },
    stack_id: "stk-feat-ledger",
    depends_on: ["network"],
    cost_month_cents: 42,
  });
  const before = structuredClone(source);
  const resource = toEnvctlResource(source);
  assert.deepEqual(resource.tags, { branch: "feat-other", team: "payments", owner: "legacy" });
  assert.deepEqual(source, before);
  assert.equal(resource.cost_month_cents, 42);
  assert.deepEqual(resource.depends_on, ["network"]);
  assert.equal(buildPlan([resource], "feat-ledger").steps.length, 0);
  for (const fields of [{}, { labels: null, tags: null }, { labels: {}, tags: {} }]) {
    const empty = toEnvctlResource(raw("empty", fields));
    assert.ok(isUntagged(empty));
    assert.deepEqual(empty.tags, {});
    assert.equal(empty.stack_id, null);
  }
});

test("label-owned resources join the plan, but unrelated dependents remain blockers", () => {
  const resources = [
    raw("network", { tags: { branch: "feat-ledger" }, stack_id: "stk-feat-ledger" }),
    raw("boot", { stack_id: "stk-feat-ledger" }),
    raw("worker", { labels: { Branch: "feat-ledger" }, depends_on: ["network", "boot"] }),
    raw("external", { labels: { Branch: "feat-payroll" }, depends_on: ["network"] }),
    raw("lookalike", { name: "feat-ledger-extra", stack_id: "stk-feat-ledger-extra" }),
  ].map(toEnvctlResource);
  const plan = buildPlan(resources, "feat-ledger");
  assert.deepEqual(plan.steps.map(r => r.id).sort(), ["boot", "network", "worker"]);
  assert.deepEqual(plan.blocked, [{ id: "network", dependents: ["external"] }]);
  assert.ok(plan.steps.findIndex(r => r.id === "worker") < plan.steps.findIndex(r => r.id === "boot"));
});
