test("CLI preserves labels across pages and tears down only the requested branch", async (t) => {
  let resources = [
    { id: "net", type: "network", tags: { branch: "feat-ledger" }, stack_id: "stk-feat-ledger", depends_on: [] },
    { id: "boot", type: "volume", stack_id: "stk-feat-ledger", depends_on: [] },
