    { id: "worker", type: "instance", labels: { bRaNcH: "feat-ledger" }, depends_on: ["net", "cdk-boot"] },
    { id: "other", type: "instance", labels: { Branch: "feat-payroll" }, depends_on: [] },
  ].map(r => ({ name: r.id, cost_month_cents: 100, ...r }));
  const requests: string[] = [];
  const deleted: string[] = [];
  const server = createServer((req, res) => {
    const url = new URL(req.url!, "http://localhost");
    requests.push(`${req.method} ${req.url}`);
    res.setHeader("content-type", "application/json");
    if (req.headers.authorization !== "Bearer test-token") {
      res.writeHead(401).end(JSON.stringify({ error: "unauthorized" }));
      return;
    }
    if (req.method === "GET" && url.pathname === "/v1/resources") {
      assert.equal(url.searchParams.get("limit"), "20");
      const cursor = url.searchParams.get("cursor")!;
      const offset = cursor === "0" ? 0 : Number(cursor.slice("page /".length));
      const next = offset + 2;
      res.end(JSON.stringify({
        resources: resources.slice(offset, next),
        next_cursor: next < resources.length ? `page /${next}` : null,
      }));
      return;
    }
    if (req.method === "DELETE") {
      const id = decodeURIComponent(url.pathname.slice("/v1/resources/".length));
      const dependents = resources.filter(r => r.depends_on.includes(id)).map(r => r.id);
      if (dependents.length) {
        res.writeHead(409).end(JSON.stringify({ error: "resource has dependents", dependents }));
        return;
      }
      deleted.push(id);
      resources = resources.filter(r => r.id !== id);
      res.end(JSON.stringify({ deleted: id }));
      return;
    }
    res.writeHead(404).end(JSON.stringify({ error: "not found" }));
  });
  await new Promise<void>(resolve => server.listen(0, "127.0.0.1", resolve));
  t.after(() => new Promise<void>((resolve, reject) => server.close(err => err ? reject(err) : resolve())));
  const address = server.address() as { port: number };
  const cli = fileURLToPath(new URL("../src/cli.ts", import.meta.url));
  const run = (...args: string[]) => new Promise<{ code: number | null; stdout: string; stderr: string }>((resolve, reject) => {
    const child = spawn(process.execPath, ["--experimental-strip-types", "--no-warnings", cli, ...args], {
      env: { ...process.env, ENVCTL_API: `http://127.0.0.1:${address.port}`, ENVCTL_TOKEN: "test-token" },
    });
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", chunk => { stdout += chunk; });
    child.stderr.on("data", chunk => { stderr += chunk; });
    child.on("error", reject);
    child.on("close", code => resolve({ code, stdout, stderr }));
  });

  const planned = await run("plan", "--branch", "feat-ledger", "--json");
  assert.equal(planned.code, 0, planned.stderr);
  const plan = JSON.parse(planned.stdout);
  assert.deepEqual(plan.blocked, []);
  assert.deepEqual(plan.steps.map((r: { id: string }) => r.id).sort(), ["boot", "cdk-boot", "legacy", "net", "worker"]);
  assert.ok(requests.some(path => path.includes("cursor=page%20%2F4")), "must follow and encode cursors");

  const listing = await run("list");
  assert.equal(listing.code, 0, listing.stderr);
  assert.match(listing.stdout, /feat-ledger\s+4/);
  assert.match(listing.stdout, /feat-payroll\s+1/);
  const gc = await run("gc", "--untagged");
  assert.equal(gc.code, 0, gc.stderr);
  assert.match(gc.stdout, /1 untagged resources/); // only the legacy stack's untagged boot volume

  resources.find(r => r.id === "other")!.depends_on = ["net"];
  const refused = await run("teardown", "--branch", "feat-ledger");
  assert.equal(refused.code, 1);
  assert.match(refused.stderr, /refusing to tear down/);
  assert.deepEqual(deleted, []);
  resources.find(r => r.id === "other")!.depends_on = [];

  const teardown = await run("teardown", "--branch", "feat-ledger");
  assert.equal(teardown.code, 0, teardown.stderr);
  assert.match(teardown.stdout, /complete \(5 resources\)/);
  assert.deepEqual(deleted, plan.steps.map((r: { id: string }) => r.id));
  assert.deepEqual(resources.map(r => r.id), ["other"]);
  const empty = await run("plan", "--branch", "feat-ledger", "--json");
  assert.equal(empty.code, 0, empty.stderr);
  assert.deepEqual(JSON.parse(empty.stdout).steps, []);
});
